SELECT session_id
FROM (
  SELECT session_id
  FROM bt_bot_session
  WHERE status_cd = '00A'
    AND bot_id = #{botId}
    AND creator_id = #{userId}

    AND ext_system_id = #{extSystemId}

  ORDER BY updated_time DESC
) TMP
WHERE 1=1
 1

SELECT a.session_id,
a.bot_id,
a.ext_system_id,
a.plat_bot_id,
a.session_title,
a.prologue,
a.updated_time,
(SELECT MAX(m.created_time) FROM bt_bot_session_msg m WHERE m.session_id = a.session_id) AS last_msg_time
FROM bt_bot_session a
WHERE a.status_cd = '00A'

  AND a.bot_id = #{query.botId}


  AND a.tenant_id = #{query.tenantId}


  AND a.space_id = #{query.spaceId}

  AND a.creator_id = #{query.userId}

  AND a.session_title LIKE

  #{query.searchContent}



  AND a.ext_system_id = #{query.extSystemId}



    AND a.is_test = 'T'


    AND a.is_test IS NULL

SELECT a.session_id, a.bot_id, a.bot_tenant_id, a.ext_system_id,
(SELECT MAX(p.plat_bot_id) FROM bt_plat_bot_info p WHERE p.bot_id = a.bot_id AND p.status_cd = '00A' AND p.status = '1') AS plat_bot_id,
COALESCE( (SELECT MAX(p.plat_bot_id) FROM bt_plat_bot_info p WHERE p.bot_id = a.bot_id AND p.status_cd = '00A' AND p.status = '1'), (SELECT MAX(bba.auth_id) FROM bt_bot_auth bba WHERE bba.bot_id = a.bot_id AND bba.status_cd = '00A') ) AS plat_bot_id,
a.session_title, a.updated_time, CASE WHEN bb.tenant_id = -1 THEN 'T' ELSE 'F' END AS isPlatformPublish FROM bt_bot_session a LEFT JOIN bt_bot bb ON bb.bot_id = a.bot_id WHERE a.status_cd = '00A'
AND a.tenant_id = #{query.tenantId}
AND space_id = #{query.spaceId}
AND a.creator_id = #{query.userId}
AND a.bot_id = #{query.botId}
AND exists(select 1 from bt_chat_bot_cfg b WHERE a.space_id = b.space_id AND ((a.bot_id = b.bot_id) OR (a.bot_id IS NULL AND a.plat_bot_id = b.bot_id)) AND a.creator_id = b.creator_id AND b.status_cd = '00A' AND b.action_type = 'mark')
AND not exists(select 1 from bt_chat_bot_cfg b WHERE a.space_id = b.space_id AND ((a.bot_id = b.bot_id) OR (a.bot_id IS NULL AND a.plat_bot_id = b.bot_id)) AND a.creator_id = b.creator_id AND b.status_cd = '00A' AND b.action_type = 'close')
AND a.is_test = 'T'
AND a.is_test IS NULL
ORDER BY a.updated_time desc

SELECT

FROM bt_bot_session a
WHERE plat_bot_id = #{platBotId}

  AND space_id = #{spaceId}

  AND status_cd = '00A'
 1

SELECT a.session_id, a.session_title, a.created_time, a.updated_time, b.bot_name, b.bot_id, d.scene_name, d.scene_id, e.real_name AS updatorName, a.bot_tenant_id FROM bt_bot_session a LEFT JOIN bt_bot b ON a.bot_id = b.bot_id LEFT JOIN bt_bot_session_msg c ON a.session_id = c.session_id LEFT JOIN bt_bot_scene d ON c.scene_id = d.scene_id LEFT JOIN bt_user e ON a.updator_id = e.user_id WHERE a.status_cd = '00A' AND a.tenant_id = #{query.tenantId}
AND a.bot_id = #{query.botId}
AND c.scene_id = #{query.sceneId}
AND a.created_time >= #{query.minBeginTime}
AND a.created_time <= #{query.maxBeginTime}
AND a.session_id = #{query.sessionId}
GROUP BY a.session_id, a.session_title, a.created_time, b.bot_name, d.scene_name, e.real_name, d.scene_id, b.bot_id, a.updated_time, a.bot_tenant_id ORDER BY a.updated_time DESC

SELECT session_id
FROM bt_bot_session
WHERE status_cd = '00A'
  AND space_id = #{spaceId}
  AND creator_id = #{userId}
  AND remark = #{groupId}

SELECT compressed_summary
FROM bt_bot_session
WHERE session_id = #{sessionId}

mapper.update:
UPDATE bt_bot_session
SET compressed_summary = #{compressedSummary}
WHERE session_id = #{sessionId}
